/**
 * The top of a post page: category, title, excerpt, the author line and an optional wide cover. Axes: layout
 * (start, center), cover (show, hide), meta (full, short), tone.
 */
import { type ReactNode } from "react";
import { Group } from "../primitives/group/group";
import { Text } from "../primitives/text/text";
import { MediaFrame } from "../components/media-frame";
import { Pill } from "../components/pill";
import { SectionFrame } from "../components/section-frame";
import { tpl } from "../utils";
import type { Post, PostLabels } from "./post-card.types";

export type PostHeaderProps = {
  id: string;
  post: Post;
  labels: PostLabels;
  level?: 1 | 2;
  layout?: "start" | "center";
  cover?: "show" | "hide";
  meta?: "full" | "short";
  tone?: "default" | "muted";
};

export function PostHeader({
  id,
  post,
  labels,
  level = 1,
  layout = "start",
  cover = "show",
  meta = "full",
  tone = "default",
}: PostHeaderProps) {
  return (
    <SectionFrame
      id={id}
      title={post.title}
      lead={post.excerpt}
      heading={{ level }}
      align={layout}
      tone={tone}
      media={{ show: ((cover as string) === "show") }}
      aside={(
        <MediaFrame alt={post.title} ratio="21/9" />
      )}
    >
      <Group
        gap="4"
        align="center"
        justify={(((layout as string) === "center") ? "center" : "start")}
        className="flex-wrap"
        data-testid="post-meta"
      >
        <MediaFrame alt={post.author} ratio="1/1" className="size-10 shrink-0 rounded-full" />
        <Text size="sm" weight="semibold">
          {post.author}
        </Text>
        <Text size="sm" className="text-muted-foreground">
          {post.date}
        </Text>
        {((meta as string) === "full") ? (
          <Text size="sm" className="text-muted-foreground">
            {tpl(labels.minutes, post.minutes)}
          </Text>
        ) : null}
        <Pill tone="blue">
          {post.category}
        </Pill>
      </Group>
    </SectionFrame>
  );
}
